import java.util.Scanner;

public class LuckyTickets {

    private static final int MOD = 998244353;
    private static final int twoPow = 23;
    private static final int ROOT = 15311432;

    private static int reverseBits(int n, int k) {
        int res = 0;
        for (int i = 0; i < k; i++) {
            res = (res << 1) | (n & 1);
            n >>= 1;
        }
        return res;
    }

    private static long powerMod(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    private static long inverseMod(long a) {
        return powerMod(a, MOD - 2);
    }

    private static long[] rootsOfUnity(int k, boolean inverse) {
        long root = powerMod(ROOT, powerMod(2, twoPow - k));
        if (inverse) {
            root = inverseMod(root);
        }
        long[] roots = new long[k];
        if (k > 0) {
            roots[k - 1] = root;
        }
        for (int i = k - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
        }
        return roots;
    }

    private static long[] bitReversalPermutation(long[] array, int k) {
        long[] result = new long[array.length];
        for (int i = 0; i < array.length; i++) {
            result[reverseBits(i, k)] = array[i];
        }
        return result;
    }

    private static long[] performNTT(long[] coef, int k, boolean inverse) {
        coef = bitReversalPermutation(coef, k);
        long[] roots = rootsOfUnity(k, inverse);
        for (int s = 0; s < k; s++) {
            int segmentSize = 1 << s;
            for (int start = 0; start < coef.length; start += 2 * segmentSize) {
                long currentRoot = 1;
                for (int j = start; j < start + segmentSize; j++) {
                    long t = (currentRoot * coef[j + segmentSize]) % MOD;
                    long u = coef[j];
                    coef[j] = (u + t) % MOD;
                    coef[j + segmentSize] = (u - t + MOD) % MOD;
                    currentRoot = (roots[s] * currentRoot) % MOD;
                }
            }
        }
        return coef;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int m = sc.nextInt();
        int[] nums = new int[m];
        int maxVal = 0;
        for (int i = 0; i < m; i++) {
            nums[i] = sc.nextInt();
            maxVal = Math.max(maxVal, nums[i]);
        }
        int minSize = n * maxVal + 1;
        int size = 1;
        int k = 0;
        while (size < minSize) {
            size <<= 1;
            k++;
        }
        long[] array = new long[size];
        for (int i = 0; i < nums.length; i++) {
            array[nums[i]] = 1;
        }
        array = performNTT(array, k, false);
        for (int i = 0; i < size; i++) {
            array[i] = powerMod(array[i], n);
        }
        array = performNTT(array, k, true);
        long totalSum = 0;
        for (int i = 0; i < size; i++) {
            totalSum = (totalSum + array[i] * array[i]) % MOD;
        }
        long invSize = inverseMod(size);
        System.out.println((((totalSum * invSize) % MOD) * invSize) % MOD);
    }
}
